 static HttpResponseMessage Response(string text)=>new(HttpStatusCode.OK){Content=new StringContent(JsonSerializer.Serialize(new{choices=new[]{new{message=new{content=text}}}}),Encoding.UTF8,"application/json")};
 static IEnumerable<DependencyObject> Walk(DependencyObject root){yield return root;foreach(var c in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var d in Walk(c))yield return d;}
 static Button Button(DependencyObject root,string text)=>Walk(root).OfType<Button>().First(b=>Equals(b.Content,text));
 static void Capture(Window window,string path){window.UpdateLayout();var e=(FrameworkElement)window.Content;var image=new System.Windows.Media.Imaging.RenderTargetBitmap((int)Math.Ceiling(e.ActualWidth),(int)Math.Ceiling(e.ActualHeight),96,96,System.Windows.Media.PixelFormats.Pbgra32);image.Render(e);var png=new System.Windows.Media.Imaging.PngBitmapEncoder();png.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(image));using var file=File.Create(path);png.Save(file);}
 sealed class PanelHandler(Func<HttpRequestMessage,Task<HttpResponseMessage>> reply):HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token)=>reply(request);}
